explanation.why:
In `lib/marked.js`, commit be27472a rewrote the `inline.text` regex so it no longer has a ` {2,}
` lookahead in its lazy loop. The new regex only stops before a hard line break through `[^ ](?= {2,}
)` or an outer alternative that is tried only after the first alternative fails. `inline.breaks` turns ` {2,}` into ` *`, so a break can have zero spaces. For `A
B` the lazy loop never stops before the `
`, because the first alternative can always reach `$`. The `text` token therefore swallows `A
B` whole, and `br` never gets a chance to match. The fix adds ` *
` as a stop condition in the lookahead group, but only for the `breaks` text regex.

fix.patch:
diff --git a/lib/marked.js b/lib/marked.js
index 86286794..53bafe97 100644
--- a/lib/marked.js
+++ b/lib/marked.js
@@ -634,7 +634,7 @@ inline.gfm.url = edit(inline.gfm.url, 'i')

 inline.breaks = merge({}, inline.gfm, {
   br: edit(inline.br).replace('{2,}', '*').getRegex(),
-  text: edit(inline.gfm.text).replace(/\{2,\}/g, '*').getRegex()
+  text: edit(inline.gfm.text).replace(/\{2,\}/g, '*').replace('|$)', '|$| *\\n)').getRegex()
 });

 /**

repro.code:
import { createRequire } from 'node:module';
const require = createRequire(import.meta.url);

const marked = require('./lib/marked.js');

const html = marked('A\nB', { breaks: true });
if (!/<p>A<br\s*\/?>\s*B<\/p>/.test(html)) {
  console.log('WHOBROKEIT_BUG: expected "<p>A<br>B</p>" with breaks enabled, got ' + JSON.stringify(html));
  process.exitCode = 1;
} else {
  process.exitCode = 0;
}
